"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[3,5,6],[5,6,3],[6,3,5],[3,6,7],[5,3,7],[6,5,7]];
const dyes=[{name:['Ruby','紅寶'],symbol:'◆',colour:'#ad2848',distance:2},{name:['Amber','琥珀'],symbol:'▲',colour:'#976100',distance:5},{name:['Sapphire','藍寶'],symbol:'●',colour:'#2459aa',distance:8}];
let variant=OrionProgress.variant('ink'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,mask=0,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function chosen(n){return dyes.filter((d,i)=>n&(1<<i)).map(d=>t(...d.name)).join(' + ')||t('None','尚未選擇');}
function toggle(i){if(solved||!Number.isInteger(i)||i<0||i>2)return;mask^=1<<i;state='ready';render();}
function resetTrial(){mask=0;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('ink')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(mask!==challenge())state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('spectrum');}render();if(solved&&stage<2)$('next').focus();}
function strip(n,label){const spots=dyes.filter((d,i)=>n&(1<<i));return `<svg viewBox="0 0 140 220" role="img" aria-label="${label}: ${spots.map(d=>d.symbol+' '+d.distance+t(' cm',' 厘米')).join(', ')||t('no spots','沒有色點')}"><rect x="28" y="18" width="90" height="184" rx="4" fill="#eee3c7"/><text x="73" y="13" text-anchor="middle" fill="#ecdbb5" font-size="12">${label}</text><line x1="28" x2="118" y1="34" y2="34" stroke="#328a94" stroke-dasharray="4 3"/><line x1="28" x2="118" y1="184" y2="184" stroke="#4c4b49"/><text x="5" y="38" fill="#dbe9e6" font-size="10">10</text><text x="13" y="188" fill="#dbe9e6" font-size="10">0</text>${spots.map(d=>`<g class="spot"><ellipse cx="73" cy="${184-d.distance*15}" rx="17" ry="10" fill="${d.colour}" opacity=".85"/><text x="73" y="${188-d.distance*15}" text-anchor="middle" fill="white" font-size="11">${d.symbol}</text><text x="5" y="${188-d.distance*15}" fill="#dbe9e6" font-size="10">${d.distance}</text></g>`).join('')}<text x="73" y="216" text-anchor="middle" fill="#dbe9e6" font-size="10">${t('distance · cm','距離 · 厘米')}</text></svg>`;}
function drawing(){return `<div class="standards">${dyes.map((d,i)=>strip(1<<i,t(...d.name))).join('')}</div>`;}
function hints(){return[t('Compare the mystery strip with the three known dyes. Look at the height of each spot above the start line.','比較神秘色譜與三種已知染料，觀察色點離起點的高度。'),t('A mixture can separate into several spots. Match every spot to a known dye under the same conditions.','混合物可以分成多個色點。在相同條件下，把每個色點與已知染料配對。'),t(`Try selecting ${chosen(challenge())}. Include all matching dyes, and leave the others out.`,`試選 ${chosen(challenge())}。選齊所有配對染料，不要加入其他染料。`)];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Inkkeeper’s Archive · Orion','墨守者檔案館 · Orion');$('stageTitle').textContent=t(`Ink ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 瓶墨水 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Archive seals · ${p} / 3`,`檔案封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();
for(let i=0;i<3;i++){const on=Boolean(mask&(1<<i)),btn=$('bit'+i);btn.disabled=solved;btn.setAttribute('aria-pressed',String(on));btn.setAttribute('aria-label',t(...dyes[i].name));btn.textContent=dyes[i].symbol+' '+t(...dyes[i].name)+(on?' ✓':'');}
$('goal').textContent=t('Which dyes made this mystery ink? Select the ingredients on the left, then compare.','神秘墨水含有哪些染料？在左邊選擇成分，再比較。');$('reading').innerHTML=`<div class="comparison ${state!=='ready'?'developed':''}">${strip(q,t('Mystery ink','神秘墨水'))}${strip(mask,t('Your mixture','你的混合物'))}</div>`;$('reference').textContent=t('Solid line: start · Dashed line: solvent front (10 cm). Same paper and solvent throughout.','實線：起點 · 虛線：溶劑前緣（10 厘米）。全程使用相同紙張和溶劑。');const messages={ready:[`Selected: ${chosen(mask)}. Compare the separated spots.`,`已選：${chosen(mask)}。比較分離後的色點。`],wrong:['Some spots are missing or extra. Compare their heights and try again.','有色點缺少或多了。比較高度，再試一次。'],success:['All spots match! You have identified this model ink.','所有色點都配對了！你找出了模型墨水的成分。']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('spectrum')?t('Spectrum Sigil saved in your collection.','色譜符印已存入收藏。'):'';}
for(let i=0;i<3;i++)$('bit'+i).onclick=()=>toggle(i);
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('ink',variant);observedVariant=OrionProgress.variant('ink');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('spectrum');render();};function syncProgress(){const v=OrionProgress.variant('ink'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('spectrum')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
